{
  "objective": "Explain the four tracking stages and how orientation is estimated through calibration, registration, integration, and drift correction.",
  "key_points": [
    {
      "text": "The tracking process consists of four stages: calibration, registration, integration, and drift correction.",
      "sentence_ids": [123],
      "about": "subject"
    },
    {
      "text": "Calibration transforms cheap sensor readings into values close to accurate sensor values using a mathematical expression derived from paired data samples.",
      "sentence_ids": [124, 125, 126, 127],
      "about": "subject"
    },
    {
      "text": "Registration sets the initial position and orientation of tracked body parts or objects using the current sensor position and the user's orientation.",
      "sentence_ids": [128],
      "about": "subject"
    },
    {
      "text": "Integration estimates orientation at any time by summing sensory values to the initial orientation obtained during registration.",
      "sentence_ids": [129, 130],
      "about": "subject"
    },
    {
      "text": "Drift correction combines orientations estimated separately by at least two sensors, for example with a gain parameter normalized between 0 and 1.",
      "sentence_ids": [131, 132, 133, 134],
      "about": "subject"
    }
  ]
}

